'use strict';(()=>{const B=RPG_BOOKS,bridge=RPG_ACCOUNT_BRIDGE,$=s=>dialog.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Math.ceil(n).toLocaleString('ko-KR');const dialog=document.createElement('dialog');dialog.className='books-dialog';dialog.id='books-dialog';dialog.innerHTML='<header><div><small>EXPEDITION CODEX</small><h2>전투 교본</h2></div><button data-books-close aria-label="전투 교본 닫기">×</button></header><div class="books-scroll"><p id="books-notice" role="status" aria-live="polite"></p><div id="books-body"></div></div>';document.body.append(dialog);const detail=document.createElement('dialog');detail.className='books-detail';detail.setAttribute('aria-labelledby','books-detail-title');document.body.append(detail);let payload,hero=0,filter='전체',chosen=null,message='';function refresh(){payload=bridge.books.view();}function say(s){message=s;$('#books-notice').textContent=s;}
const art={mastery:'<path d="M21 49V21l11-5 11 5v28l-11-5z"/><path d="M32 16v28m-7-17 4 2m6 0 4-2m-14 8 4 2m6 0 4-2"/>',chain:'<path d="m18 37 9-9m10 8 9-9"/><rect x="13" y="27" width="25" height="12" rx="6" transform="rotate(-40 25 33)"/><rect x="27" y="27" width="25" height="12" rx="6" transform="rotate(-40 39 33)"/>',execute:'<path d="m20 45 25-27 4 5-25 27m-9-13 16 15m-14-4-5 6"/><path d="M15 18h12m-6-6v12"/>',area:'<circle cx="32" cy="32" r="9"/><path d="M32 10v10m0 24v10M10 32h10m24 0h10M17 17l7 7m16 16 7 7m0-30-7 7M24 40l-7 7"/>',boss:'<path d="m17 49 3-27 12-9 12 9 3 27-15-7zM24 29h3m10 0h3m-14 7h12m-6-23v9"/><path d="m13 52 38-39"/>',focus:'<circle cx="32" cy="32" r="19"/><circle cx="32" cy="32" r="10"/><path d="M32 8v15m0 18v15M8 32h15m18 0h15"/>',grit:'<path d="m32 11 19 8-3 21-16 13-16-13-3-21z"/><path d="m33 19-6 14h9l-5 13"/>',aid:'<rect x="15" y="18" width="34" height="33" rx="6"/><path d="M25 18v-6h14v6m-7 8v17m-8-8h16"/>',mana:'<path d="M32 10s-16 19-16 29a16 16 0 0 0 32 0C48 29 32 10 32 10z"/><path d="M24 38a8 8 0 0 0 13 6m2-2 1 6-6-1"/>',summon:'<path d="M19 45c0-16 26-16 26 0 0 11-26 11-26 0z"/><ellipse cx="16" cy="26" rx="5" ry="7"/><ellipse cx="28" cy="19" rx="5" ry="7"/><ellipse cx="40" cy="20" rx="5" ry="7"/><ellipse cx="49" cy="29" rx="5" ry="7"/>',grace:'<path d="M32 48V23m-9 10h18M28 18h8"/><path d="M26 30 12 23l4 16 10 5m12-14 14-7-4 16-10 5"/><ellipse cx="32" cy="13" rx="11" ry="4"/>',retort:'<path d="m35 12 15 8-3 23-12 9-12-9-2-14"/><path d="M16 45V27h22m-8-8 8 8-8 8"/>'};
function icon(id){return `<span class="book-art book-art-${id}" aria-hidden="true"><svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">${art[id]||art.mastery}</svg></span>`;}
const effects={mastery:'피해 · 회복 · 보호막 +5%',chain:'처치 시 스킬 재사용 −0.3초',execute:'빈사 상태 일반 적 피해 +15%',area:'3마리 이상 범위 피해 +8%',boss:'보스 피해 +8%',focus:'보스 집중 공격 피해 최대 +8%',grit:'빈사 상태 받는 피해 −15%',aid:'위급 시 최대 체력 8% 회복',mana:'마력 스킬 3회 → 마력 5% 회복',summon:'소환수 · 포탑 피해 +8%',grace:'치유 · 보호막 대상 받는 피해 −5%',retort:'피격 후 다음 공격에 추가 피해 40%'};

const conditions={mastery:'모든 피해 · 회복 · 보호막에 적용',chain:'일반 스킬만 · 초당 1회',execute:'대상 체력 30% 이하 · 보스 제외',area:'일반 적 3마리 이상 적중',boss:'보스 대상 공격에 적용',focus:'2초마다 +1% · 공격 중단 4초면 초기화',grit:'내 체력 30% 이하일 때',aid:'내 체력 25% 이하 · 재사용 30초',mana:'마력 직업 전용 · 재사용 8초',summon:'소환수 · 포탑을 사용하는 직업 전용',grace:'3초 지속 · 기본 재생 제외 · 중첩 불가',retort:'실제 피해를 받은 후 · 재사용 3초'};
function render(){const h=payload.heroes[hero],book=payload.books,owned=book.owned,list=book.loadouts[hero]||[],n=B.slots(h.level),rec=B.recommend(hero,h.cell,RPG_DATA),def=id=>B.defs.find(d=>d.id===id);$('#books-body').innerHTML=`<section class="books-character"><div><small>원정대 공통 해금 · 캐릭터별 장착</small><label for="books-hero">교본을 장착할 캐릭터</label><select id="books-hero">${payload.heroes.map((h,i)=>h.recruited?`<option value="${i}" ${hero===i?'selected':''}>${esc(RPG_DATA.characters[i].name)} · Lv.${h.level}</option>`:'').join('')}</select></div><strong>${fmt(h.gold)}<small> G</small></strong></section><section class="books-loadout"><div class="books-section-title"><h3>현재 장착</h3><span>${list.length} / ${n}</span></div><div class="books-slots">${[0,1,2].map(i=>`<button ${i<n?`data-slot="${i}"`: 'disabled'} class="${list[i]?'filled':''}">${list[i]?icon(list[i]):'<span class="book-empty" aria-hidden="true">＋</span>'}<small>${i<n?`장착 ${i+1}`:'잠김'}</small><b>${i>=n?'Lv.'+[30,45,60][i]:list[i]?esc(def(list[i]).name):'＋ 교본 선택'}</b>${list[i]?`<span>${effects[list[i]]}</span><em>상세 · 교체</em>`:''}</button>`).join('')}</div><p>${n?list.length?'장착 교본을 누르면 효과를 확인하거나 해제할 수 있어요.':'아래 교본을 선택해 첫 특성을 장착하세요.':'Lv.30 / 45 / 60에 장착 칸이 열려요.'}</p></section><div class="books-meta"><span>보유 교본 <b>${owned.length} / ${B.defs.length}</b></span><span>실패 없음 · 교체 무료</span></div><nav class="books-filters" aria-label="교본 분류">${['전체','사냥','보스','생존·지원','소환'].map(x=>`<button data-filter="${x}" aria-pressed="${x===filter}">${x}</button>`).join('')}</nav><div class="books-grid">${B.defs.filter(d=>filter==='전체'||d.group===filter).sort((a,b)=>Number(rec.includes(b.id))-Number(rec.includes(a.id))).map(d=>{const have=owned.includes(d.id),eq=list.includes(d.id),ok=B.compatible(d.id,hero,h.cell,RPG_DATA);return `<button class="book-card ${eq?'equipped':''}" data-book="${d.id}">${icon(d.id)}<span class="book-copy"><small>${d.group}${rec.includes(d.id)&&ok?' · 추천':''}</small><strong>${d.name}</strong><span class="book-effect">${effects[d.id]}</span><span class="book-condition">${conditions[d.id]}</span></span><span class="book-card-state ${eq?'on':''}">${eq?'✓ 장착 중':have?'보유':'미습득'}<small>${!ok?'직업 조건 확인':eq?'상세 보기':have?'장착하기':d.cost?fmt(d.cost)+' G로 배우기':'Lv.30 무료'}</small></span></button>`;}).join('')}</div><p class="books-footnote">현재 사냥에 적용됩니다. 조건부 효과는 기본 전투력 숫자에 합산하지 않아요.<br>구매 골드는 선택한 캐릭터에게서 차감됩니다.</p>`;$('#books-hero').onchange=e=>{hero=Number(e.target.value);render();};say(message);}
function show(id){chosen=id;const d=B.defs.find(x=>x.id===id),h=payload.heroes[hero],have=payload.books.owned.includes(id),eq=payload.books.loadouts[hero]?.includes(id),ok=B.compatible(id,hero,h.cell,RPG_DATA),n=B.slots(h.level);detail.innerHTML=`<button class="books-detail-close" data-detail-close aria-label="교본 상세 닫기">×</button>${icon(d.id)}<small>${d.group} · ${have?'보유 교본':'영구 해금'}</small><h2 id="books-detail-title">${d.name}</h2><p class="book-detail-effect">${effects[d.id]}</p><p>${d.text}</p><div class="books-detail-info">${ok?'이 캐릭터에게 적용할 수 있어요.':'현재 직업에는 효과가 없어 장착할 수 없어요.'}<br>원정대 공통 해금 · 실패 없음 · 장착 교체 무료</div>${!have?`<dl><div><dt>결제 캐릭터</dt><dd>${esc(RPG_DATA.characters[hero].name)}</dd></div><div><dt>보유 골드</dt><dd>${fmt(h.gold)} G</dd></div><div><dt>구매 후</dt><dd>${fmt(Math.max(0,h.gold-d.cost))} G</dd></div></dl><button class="books-primary" data-buy="${id}" ${h.level<30||h.gold<d.cost||!d.cost?'disabled':''}>${h.level<30?'Lv.30부터 해금 가능':!d.cost?'Lv.30에 무료 지급':h.gold<d.cost?fmt(d.cost-h.gold)+' G 부족':fmt(d.cost)+' G로 배우기'}</button>`:`<button class="books-primary" data-equip="${id}" ${!ok||!n?'disabled':''}>${!n?'Lv.30에 장착 가능':eq?'장착 해제':'장착하기'}</button><div id="books-replace"></div>`}<p class="books-detail-status" role="status" aria-live="polite"></p>`;if(!detail.open)detail.showModal();}
function change(action,id,replace){try{const result=bridge.books.change(action,id,hero,replace);if(!result)throw Error('조건을 다시 확인해 주세요.');refresh();message=action==='buy'?'교본 해금 완료 · 장착하기를 눌러 적용하세요.':'장착 구성을 저장했어요.';render();if(action==='buy'){show(id);detail.querySelector('.books-detail-status').textContent='해금 완료 · 다른 캐릭터도 사용할 수 있어요.';}else detail.close();}catch(e){if(detail.open)detail.querySelector('.books-detail-status').textContent=e.message;else say(e.message);}}
function close(){detail.close();dialog.close();bridge.books.edit(false);bridge.pause(false);document.dispatchEvent(new Event('rpg:hub-open'));}document.addEventListener('rpg:books-open',e=>{try{bridge.books.edit(true);refresh();hero=Number.isInteger(e.detail?.hero)&&payload.heroes[e.detail.hero]?.recruited?e.detail.hero:Number.isInteger(payload.active)&&payload.heroes[payload.active]?.recruited?payload.active:payload.heroes.findIndex(h=>h.recruited);if(hero<0)throw Error('먼저 캐릭터를 원정대에 추가해 주세요.');message='교본은 한 번 배우면 원정대 전체가 사용해요. 장착 효과는 캐릭터마다 달라요.';filter='전체';render();bridge.pause(true);dialog.showModal();}catch(e){bridge.books.edit(false);$('#books-body').innerHTML='<p class="books-footnote">캐릭터를 원정대에 추가하면 교본을 확인할 수 있어요.</p>';say(e.message);bridge.pause(true);if(!dialog.open)dialog.showModal();}});dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-books-close'))return close();if(b.dataset.filter){filter=b.dataset.filter;render();}if(b.dataset.book)show(b.dataset.book);if(b.dataset.slot!==undefined){const id=payload.books.loadouts[hero]?.[Number(b.dataset.slot)];if(id)show(id);else{filter='전체';render();$('#books-notice').textContent='목록에서 교본을 선택해 장착하세요.';}}});detail.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-detail-close'))return detail.close();if(b.dataset.buy)return change('buy',b.dataset.buy);if(b.dataset.replace)return change('equip',chosen,b.dataset.replace);if(b.dataset.equip){const list=payload.books.loadouts[hero]||[];if(!list.includes(chosen)&&list.length>=B.slots(payload.heroes[hero].level))detail.querySelector('#books-replace').innerHTML='<p>교체할 교본을 선택하세요.</p>'+list.map(id=>`<button data-replace="${id}"><strong>${B.defs.find(d=>d.id===id).name}</strong><span>${effects[id]}</span><span class="book-replace-arrow">↓ ${effects[chosen]}</span><b>이 교본과 교체</b></button>`).join('');else change('equip',chosen);}});document.addEventListener('rpg:progress-applied',()=>{if(dialog.open){detail.close();dialog.close();bridge.books.edit(false);bridge.pause(false);}});document.addEventListener('rpg:session-state',e=>{if(e.detail.blocked&&dialog.open){detail.close();dialog.close();bridge.books.edit(false);bridge.pause(false);}});})();
